#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."

if ! command -v godot >/dev/null; then
	echo "godot not on PATH (need Godot 4.7.2)" >&2
	exit 1
fi

version="$(sed -n 's/^config\/version="\(.*\)"/\1/p' app/project.godot)"
stamp="$(date -u +%Y-%m-%dT%H:%MZ)"
hash="$(git rev-parse --short HEAD 2>/dev/null || echo nogit)"

cat > app/scripts/build_version.gd <<EOF
# Generated by tools/export.sh — do not edit.
const TEXT := "v${version} · ${stamp} · ${hash}"
EOF
echo "stamping: v${version} · ${stamp} · ${hash}"

godot --headless --path app --export-release "Linux ARM64" "$PWD/build/portalsmash.arm64"

launcher_name="Portal Smash v${version} · ${stamp} · ${hash}"
printf '%s\n' "$launcher_name" > build/launcher-name.txt
echo "launcher name (paste into Devkit Client 'Name'): $launcher_name"
echo "saved to build/launcher-name.txt"
